def _flush_deferred_checks(schema_editor):
    # Run deferred FK checks now so the ALTER TABLEs that follow in this
    # transaction don't fail with "pending trigger events" on PostgreSQL.
    if schema_editor.connection.vendor == "postgresql":
        schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")
        schema_editor.execute("SET CONSTRAINTS ALL DEFERRED")


def carry_over_gemini_models(apps, schema_editor):
    """Each mode keeps the Gemini model it already had; unset prices become free (0)."""
    AIMode = apps.get_model("ai_services", "AIMode")
    AIModelConfig = apps.get_model("ai_services", "AIModelConfig")
    for mode in AIMode.objects.all():
        mode.model_id = mode.gemini_model_id
        if mode.model_id is None:
            mode.is_enabled = False
        mode.save(update_fields=["model", "is_enabled"])
    AIModelConfig.objects.filter(input_price_per_million__isnull=True).update(
        input_price_per_million=0
    )
    AIModelConfig.objects.filter(output_price_per_million__isnull=True).update(
        output_price_per_million=0
    )
    _flush_deferred_checks(schema_editor)


def drop_other_providers(apps, schema_editor):
    """Only Gemini is supported now: remove OpenAI and Anthropic model rows."""
    AIModelConfig = apps.get_model("ai_services", "AIModelConfig")
    AIModelConfig.objects.exclude(provider="gemini").delete()
    _flush_deferred_checks(schema_editor)


